import { clamp } from './utils.js';

export class Input {
  constructor() {
    this.keys = new Set();          // códigos atualmente pressionados
    this.pressed = new Set();       // códigos pressionados neste frame
    this.mouse = { x: innerWidth / 2, y: innerHeight / 2, dx: 0, dy: 0 };
    this.rightDown = false;
    this.leftPressed = false;
    this.wheel = 0;
    this.isTouch = 'ontouchstart' in window && navigator.maxTouchPoints > 0;
    // mobile
    this.joy = { x: 0, y: 0, active: false };
    this.mBtn = {};                 // ações mobile "pressionadas"
    this.mPressed = {};
    this.lookDX = 0; this.lookDY = 0;
    this.enabled = true;
    this._bind();
  }
  _bind() {
    addEventListener('keydown', e => {
      if (!this.enabled) return;
      if (['Space','Tab','F1','F3'].includes(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      this.pressed.add(e.code);
    });
    addEventListener('keyup', e => this.keys.delete(e.code));
    addEventListener('blur', () => { this.keys.clear(); this.rightDown = false; });

    const cv = document.getElementById('app');
    cv.addEventListener('mousedown', e => {
      if (!this.enabled) return;
      if (e.button === 0) this.leftPressed = true;
      if (e.button === 2) this.rightDown = true;
    });
    addEventListener('mouseup', e => {
      if (e.button === 0) this.leftPressed = false;
      if (e.button === 2) this.rightDown = false;
    });
    addEventListener('mousemove', e => {
      this.mouse.x = e.clientX; this.mouse.y = e.clientY;
      if (this.rightDown) { this.mouse.dx += e.movementX || 0; this.mouse.dy += e.movementY || 0; }
    });
    addEventListener('wheel', e => { this.wheel += Math.sign(e.deltaY); }, { passive: true });
    addEventListener('contextmenu', e => e.preventDefault());

    /* -------- Touch -------- */
    if (this.isTouch) {
      const joy = document.getElementById('joystick'), stick = document.getElementById('joy-stick');
      let joyId = null;
      const jrect = () => joy.getBoundingClientRect();
      const onJoyMove = t => {
        const r = jrect(), cx = r.left + r.width / 2, cy = r.top + r.height / 2;
        let dx = (t.clientX - cx) / (r.width / 2), dy = (t.clientY - cy) / (r.height / 2);
        const len = Math.hypot(dx, dy);
        if (len > 1) { dx /= len; dy /= len; }
        this.joy.x = dx; this.joy.y = dy; this.joy.active = true;
        stick.style.transform = `translate(${dx * 32}px,${dy * 32}px)`;
      };
      joy.addEventListener('touchstart', e => {
        const t = e.changedTouches[0]; joyId = t.identifier; onJoyMove(t); e.preventDefault();
      }, { passive: false });
      addEventListener('touchmove', e => {
        for (const t of e.changedTouches) {
          if (t.identifier === joyId) onJoyMove(t);
        }
      }, { passive: true });
      addEventListener('touchend', e => {
        for (const t of e.changedTouches) {
          if (t.identifier === joyId) {
            joyId = null; this.joy.x = 0; this.joy.y = 0; this.joy.active = false;
            stick.style.transform = '';
          }
        }
      });
      // botões de ação
      document.querySelectorAll('.m-btn').forEach(btn => {
        const act = btn.dataset.act;
        btn.addEventListener('touchstart', e => { this.mBtn[act] = true; this.mPressed[act] = true; e.preventDefault(); }, { passive: false });
        btn.addEventListener('touchend', () => { this.mBtn[act] = false; });
      });
      // câmera por toque na metade direita
      const look = document.getElementById('m-look');
      let lookId = null, lx = 0, ly = 0;
      look.addEventListener('touchstart', e => {
        const t = e.changedTouches[0]; lookId = t.identifier; lx = t.clientX; ly = t.clientY; e.preventDefault();
      }, { passive: false });
      look.addEventListener('touchmove', e => {
        for (const t of e.changedTouches) if (t.identifier === lookId) {
          this.lookDX += t.clientX - lx; this.lookDY += t.clientY - ly;
          lx = t.clientX; ly = t.clientY;
        }
      }, { passive: true });
      look.addEventListener('touchend', e => {
        for (const t of e.changedTouches) if (t.identifier === lookId) lookId = null;
      });
    }
  }

  isDown(code) { return this.keys.has(code) || this.mBtn[mapToAction(code)]; }
  wasPressed(code) { return this.pressed.has(code) || this.mPressed[mapToAction(code)]; }

  /* vetor de movimento combinado (teclado + joystick) */
  moveVector() {
    let x = 0, y = 0;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y -= 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y += 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (this.joy.active) { x += this.joy.x; y += this.joy.y; }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    return { x, y, len: Math.min(len, 1) };
  }

  /* deltas de câmera (mouse arrastando com botão direito + toque) */
  cameraDelta() {
    let dx = this.mouse.dx + this.lookDX, dy = this.mouse.dy + this.lookDY;
    this.mouse.dx = 0; this.mouse.dy = 0; this.lookDX = 0; this.lookDY = 0;
    return [dx, dy];
  }
  endFrame() {
    this.pressed.clear();
    this.mPressed = {};
    this.wheel = 0;
    this.leftPressed = false;
  }
}

/* mapeia códigos de teclado para ações mobile equivalentes */
function mapToAction(code) {
  switch (code) {
    case 'KeyE': return 'interact';
    default: return null;
  }
}

/* =========================================================
 * Aetheria — Áudio procedural (WebAudio, sem arquivos externos)
 * SFX sintetizados + trilha musical procedural por contexto
 * ========================================================= */
export class AudioSys {
  constructor() {
    this.ctx = null;
    this.musicVol = 0.55;
    this.sfxVol = 0.7;
    this.mood = 'village';
    this._nextNote = 0;
    this._step = 0;
    this._noiseBuf = null;
    this._enabled = true;
  }
  /* deve ser chamado após um gesto do usuário */
  ensure() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return true; }
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) { this._enabled = false; return false; }
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.9;
      this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = this.musicVol;
      this.musicGain.connect(this.master);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = this.sfxVol;
      this.sfxGain.connect(this.master);
      // buffer de ruído reutilizável
      const len = this.ctx.sampleRate * 1;
      this._noiseBuf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const d = this._noiseBuf.getChannelData(0);
      for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
      this._nextNote = this.ctx.currentTime + 0.1;
      return true;
    } catch (e) { console.warn('Áudio indisponível:', e); this._enabled = false; return false; }
  }
  setVolumes(music, sfx) {
    this.musicVol = music; this.sfxVol = sfx;
    if (this.ctx) {
      this.musicGain.gain.value = music;
      this.sfxGain.gain.value = sfx;
    }
  }

  /* ============ SFX ============ */
  _osc(type, freq, dur, vol, { slide = 0, delay = 0, dest } = {}) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(dest || this.sfxGain);
    o.start(t); o.stop(t + dur + 0.05);
  }
  _noise(dur, vol, { freq = 800, q = 1, slide = 0, delay = 0 } = {}) {
    if (!this.ctx || !this._noiseBuf) return;
    const t = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource(); src.buffer = this._noiseBuf;
    const f = this.ctx.createBiquadFilter(); f.type = 'bandpass'; f.frequency.setValueAtTime(freq, t); f.Q.value = q;
    if (slide) f.frequency.exponentialRampToValueAtTime(Math.max(40, freq + slide), t + dur);
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.connect(f); f.connect(g); g.connect(this.sfxGain);
    src.start(t); src.stop(t + dur + 0.05);
  }
  play(name, vol = 1) {
    if (!this.ctx) return;
    try {
      switch (name) {
        case 'swing': this._noise(0.12, 0.25 * vol, { freq: 1400, slide: -900 }); break;
        case 'sword': this._noise(0.09, 0.3 * vol, { freq: 2200, slide: -1400 }); this._osc('square', 220, 0.06, 0.08 * vol, { slide: -120 }); break;
        case 'hit': this._noise(0.1, 0.5 * vol, { freq: 300, slide: -180 }); this._osc('sine', 110, 0.12, 0.3 * vol, { slide: -60 }); break;
        case 'crit': this._noise(0.14, 0.6 * vol, { freq: 500, slide: -400 }); this._osc('sine', 90, 0.18, 0.4 * vol, { slide: -50 }); this._osc('square', 660, 0.08, 0.12 * vol, { slide: 300 }); break;
        case 'block': this._osc('square', 180, 0.1, 0.25 * vol, { slide: -60 }); this._noise(0.08, 0.3 * vol, { freq: 900 }); break;
        case 'dodge': this._noise(0.2, 0.15 * vol, { freq: 500, slide: 300 }); break;
        case 'step': this._noise(0.05, 0.08 * vol, { freq: 260, slide: -120 }); break;
        case 'jump': this._osc('sine', 280, 0.15, 0.12 * vol, { slide: 200 }); break;
        case 'hurt': this._osc('sawtooth', 160, 0.2, 0.25 * vol, { slide: -90 }); break;
        case 'die': this._osc('sawtooth', 200, 0.7, 0.3 * vol, { slide: -170 }); break;
        case 'goblin': this._osc('sawtooth', rand2(300, 480), 0.15, 0.18 * vol, { slide: -140 }); break;
        case 'goblinDie': this._osc('sawtooth', 320, 0.4, 0.22 * vol, { slide: -260 }); break;
        case 'wolf': this._osc('sawtooth', 200, 0.35, 0.2 * vol, { slide: 120 }); break;
        case 'arrow': this._noise(0.18, 0.2 * vol, { freq: 1800, slide: -1200 }); break;
        case 'chest': this._osc('triangle', 320, 0.12, 0.2 * vol); this._osc('triangle', 480, 0.18, 0.18 * vol, { delay: 0.1 }); break;
        case 'coin': this._osc('sine', 880, 0.1, 0.15 * vol); this._osc('sine', 1320, 0.14, 0.12 * vol, { delay: 0.06 }); break;
        case 'potion': this._osc('sine', 520, 0.12, 0.18 * vol, { slide: 260 }); this._osc('sine', 780, 0.16, 0.14 * vol, { delay: 0.09 }); break;
        case 'bell': for (let i = 0; i < 3; i++) { this._osc('sine', 196, 1.6, 0.3 * vol, { delay: i * 1.1 }); this._osc('sine', 392, 1.2, 0.12 * vol, { delay: i * 1.1 }); } break;
        case 'door': this._noise(0.3, 0.2 * vol, { freq: 140, slide: 60 }); break;
        case 'ui': this._osc('triangle', 640, 0.06, 0.12 * vol); break;
        case 'open': this._noise(0.25, 0.2 * vol, { freq: 600, slide: 400 }); break;
        case 'levelup': [523, 659, 784, 1047].forEach((f, i) => this._osc('triangle', f, 0.3, 0.2 * vol, { delay: i * 0.11 })); break;
        case 'quest': [659, 784, 988].forEach((f, i) => this._osc('triangle', f, 0.35, 0.16 * vol, { delay: i * 0.13 })); break;
        case 'page': this._noise(0.3, 0.18 * vol, { freq: 1100, slide: 500 }); break;
        case 'heal': [440, 554, 659].forEach((f, i) => this._osc('sine', f, 0.4, 0.14 * vol, { delay: i * 0.1 })); break;
        /* magias elementais */
        case 'm_fire': this._noise(0.5, 0.35 * vol, { freq: 900, slide: -500 }); this._osc('sawtooth', 120, 0.4, 0.2 * vol, { slide: -40 }); break;
        case 'm_fireHit': this._noise(0.4, 0.55 * vol, { freq: 400, slide: -320 }); this._osc('sine', 70, 0.35, 0.4 * vol, { slide: -30 }); break;
        case 'm_water': this._noise(0.45, 0.3 * vol, { freq: 1200, q: 3, slide: 600 }); this._osc('sine', 300, 0.35, 0.16 * vol, { slide: 180 }); break;
        case 'm_waterHit': this._noise(0.3, 0.45 * vol, { freq: 800, slide: -500 }); break;
        case 'm_lightning': this._noise(0.25, 0.5 * vol, { freq: 2600, slide: -2200 }); this._osc('square', 1400, 0.12, 0.14 * vol, { slide: -1100 }); break;
        case 'm_earth': this._osc('sine', 65, 0.5, 0.42 * vol, { slide: -25 }); this._noise(0.4, 0.3 * vol, { freq: 200, slide: -120 }); break;
        case 'm_wind': this._noise(0.7, 0.28 * vol, { freq: 700, q: 2, slide: 500 }); break;
        case 'm_ice': this._osc('triangle', 1500, 0.25, 0.2 * vol, { slide: 900 }); this._noise(0.2, 0.2 * vol, { freq: 3000, slide: 1000 }); break;
        case 'm_iceHit': this._osc('triangle', 1900, 0.15, 0.28 * vol, { slide: -1400 }); this._noise(0.15, 0.3 * vol, { freq: 2600, slide: -1800 }); break;
        case 'm_cast': this._osc('sine', 440, 0.3, 0.12 * vol, { slide: 320 }); break;
        case 'grimoire': this._noise(0.4, 0.15 * vol, { freq: 900, slide: 700 }); this._osc('sine', 523, 0.5, 0.1 * vol, { slide: 200 }); break;
        case 'element': [261, 329, 392, 523, 659, 784].forEach((f, i) => this._osc('sine', f, 1.2, 0.18 * vol, { delay: i * 0.22 })); break;
        case 'roar': this._osc('sawtooth', 80, 1.1, 0.4 * vol, { slide: -30 }); this._noise(1.0, 0.3 * vol, { freq: 220, slide: -120 }); break;
        case 'thunder': this._noise(1.4, 0.6 * vol, { freq: 90, slide: -40 }); break;
        case 'night': this._osc('sine', 660, 0.4, 0.05 * vol); break;
      }
    } catch (e) { /* áudio nunca deve quebrar o jogo */ }
  }
  playAt(name, vol, dist, maxDist = 40) {
    const f = Math.max(0, 1 - dist / maxDist);
    if (f > 0.02) this.play(name, vol * f);
  }

  /* ============ Música procedural ============ */
  setMood(mood) { if (mood !== this.mood) { this.mood = mood; this._step = 0; } }
  _patterns = {
    village:   { tempo: 0.42, scale: [0, 2, 4, 7, 9, 12, 14], root: 261.6, bass: [0, 0, 5, 5, 3, 3, 5, 5], lead: [0, 4, 2, 7, 4, 9, 7, 12], wave: 'triangle', bassWave: 'sine', vol: 0.09 },
    city:      { tempo: 0.38, scale: [0, 2, 4, 5, 7, 9, 11], root: 233.1, bass: [0, 0, 4, 4, 5, 5, 7, 7], lead: [7, 4, 5, 2, 0, 4, 7, 9], wave: 'triangle', bassWave: 'sine', vol: 0.085 },
    explore:   { tempo: 0.5,  scale: [0, 2, 3, 5, 7, 8, 10], root: 220, bass: [0, 0, 3, 3, 5, 5, 3, 3], lead: [0, 3, 7, 5, 3, 7, 10, 7], wave: 'triangle', bassWave: 'sine', vol: 0.08 },
    combat:    { tempo: 0.24, scale: [0, 2, 3, 5, 7, 8, 10, 12], root: 174.6, bass: [0, 0, 0, 3, 5, 3, 0, 2], lead: [7, 5, 3, 7, 10, 7, 5, 3], wave: 'sawtooth', bassWave: 'square', vol: 0.07 },
    dungeon:   { tempo: 0.66, scale: [0, 1, 3, 5, 6, 8, 10], root: 130.8, bass: [0, 0, 6, 6], lead: [0, 6, 3, 6], wave: 'sine', bassWave: 'sine', vol: 0.07 },
    boss:      { tempo: 0.22, scale: [0, 1, 3, 5, 6, 8, 10, 12], root: 146.8, bass: [0, 0, 6, 0, 8, 6, 5, 3], lead: [12, 10, 8, 6, 8, 10, 12, 10], wave: 'sawtooth', bassWave: 'square', vol: 0.075 },
    invasion:  { tempo: 0.26, scale: [0, 2, 3, 5, 7, 8, 10], root: 155.6, bass: [0, 0, 0, 5, 0, 0, 3, 2], lead: [3, 7, 3, 10, 7, 3, 5, 2], wave: 'sawtooth', bassWave: 'square', vol: 0.075 },
    story:     { tempo: 0.6,  scale: [0, 2, 4, 5, 7, 9, 11], root: 196, bass: [0, 0, 5, 5], lead: [0, 4, 7, 9, 7, 4, 2, 0], wave: 'sine', bassWave: 'sine', vol: 0.08 },
  };
  updateMusic() {
    if (!this.ctx || !this._enabled) return;
    const p = this._patterns[this.mood] || this._patterns.explore;
    const now = this.ctx.currentTime;
    while (this._nextNote < now + 0.25) {
      const t = Math.max(this._nextNote, now + 0.02);
      const i = this._step % p.bass.length;
      // baixo
      this._note(p.root * Math.pow(2, p.bass[i] / 12) / 2, p.tempo * 0.9, p.vol * 1.6, p.bassWave, t);
      // melodia (nem sempre — deixa respirar)
      if (this._step % 2 === 0 || Math.random() < 0.6) {
        const li = Math.floor(this._step / 2) % p.lead.length;
        this._note(p.root * Math.pow(2, p.lead[li] / 12), p.tempo * 0.8, p.vol, p.wave, t);
      }
      this._nextNote += p.tempo;
      this._step++;
    }
  }
  _note(freq, dur, vol, wave, t) {
    const o = this.ctx.createOscillator(), g = this.ctx.createGain();
    o.type = wave; o.frequency.value = freq;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.musicGain);
    o.start(t); o.stop(t + dur + 0.05);
  }
}
function rand2(a, b) { return a + Math.random() * (b - a); }

/* =========================================================
 * Aetheria — Sistema de partículas (pool única, shader de pontos)
 * + anéis de choque e flashes de luz reutilizáveis
 * ========================================================= */
import * as THREE from '../../vendor/three.module.js';
import { rand, chance } from '../core/utils.js';

const MAX_P = 2200;

const vert = `
attribute float size; attribute float alpha; attribute vec3 pcolor;
varying float vA; varying vec3 vC;
void main(){
  vA = alpha; vC = pcolor;
  vec4 mv = modelViewMatrix * vec4(position,1.0);
  gl_PointSize = size * (260.0 / -mv.z);
  gl_Position = projectionMatrix * mv;
}`;
const frag = `
varying float vA; varying vec3 vC;
void main(){
  vec2 uv = gl_PointCoord - 0.5;
  float d = length(uv);
  if(d > 0.5) discard;
  float a = smoothstep(0.5, 0.08, d) * vA;
  gl_FragColor = vec4(vC, a);
}`;

export class Particles {
  constructor(scene) {
    this.scene = scene;
    this.count = MAX_P;
    this.pos = new Float32Array(MAX_P * 3);
    this.col = new Float32Array(MAX_P * 3);
    this.size = new Float32Array(MAX_P);
    this.alpha = new Float32Array(MAX_P);
    this.vel = new Float32Array(MAX_P * 3);
    this.life = new Float32Array(MAX_P);
    this.maxLife = new Float32Array(MAX_P);
    this.grav = new Float32Array(MAX_P);
    this.drag = new Float32Array(MAX_P);
    this.alpha0 = new Float32Array(MAX_P);
    this.cursor = 0;
    this.alive = 0;

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('pcolor', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(this.size, 1));
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.alpha, 1));
    const mat = new THREE.ShaderMaterial({
      vertexShader: vert, fragmentShader: frag,
      transparent: true, depthWrite: false, blending: THREE.AdditiveBlending
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);

    this.quality = 2; // 2 alta, 1 média, 0 baixa
    this._tmpColor = new THREE.Color();
    this._ringPool = [];
    this._lightPool = [];
  }

  spawn(pos, opts = {}) {
    const n = Math.round((opts.count || 12) * (this.quality === 2 ? 1 : this.quality === 1 ? 0.55 : 0.3));
    const color = this._tmpColor.set(opts.color ?? 0xffffff);
    const speed = opts.speed ?? 3, spread = opts.spread ?? 1;
    const life = opts.life ?? 0.7, size = opts.size ?? 6;
    const grav = opts.gravity ?? 0, drag = opts.drag ?? 1.5;
    const dir = opts.dir, cone = opts.cone;
    for (let k = 0; k < n; k++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % MAX_P;
      const i3 = i * 3;
      this.pos[i3] = pos.x + rand(-spread, spread) * 0.4;
      this.pos[i3 + 1] = pos.y + rand(-spread, spread) * 0.4;
      this.pos[i3 + 2] = pos.z + rand(-spread, spread) * 0.4;
      let vx, vy, vz;
      if (dir) {
        const s = speed * rand(0.6, 1.4);
        vx = dir.x * s + rand(-1, 1) * spread; vy = dir.y * s + rand(-1, 1) * spread; vz = dir.z * s + rand(-1, 1) * spread;
      } else {
        const th = rand(0, Math.PI * 2), ph = Math.acos(rand(-1, 1));
        const s = speed * rand(0.3, 1);
        vx = Math.sin(ph) * Math.cos(th) * s;
        vy = Math.abs(Math.cos(ph)) * s * (opts.upBias ? 1.4 : 1) * 0.7 + (opts.upBias ?? 0);
        vz = Math.sin(ph) * Math.sin(th) * s;
      }
      if (cone) { vy += cone * rand(0.5, 1); }
      this.vel[i3] = vx; this.vel[i3 + 1] = vy; this.vel[i3 + 2] = vz;
      const vj = rand(0.75, 1.25);
      this.life[i] = life * vj; this.maxLife[i] = this.life[i];
      this.size[i] = size * rand(0.6, 1.5);
      this.grav[i] = grav; this.drag[i] = drag;
      this.alpha0[i] = opts.alpha ?? 1;
      const cvar = opts.colorJitter ?? 0.15;
      this.col[i3] = Math.min(1, color.r * (1 + rand(-cvar, cvar)));
      this.col[i3 + 1] = Math.min(1, color.g * (1 + rand(-cvar, cvar)));
      this.col[i3 + 2] = Math.min(1, color.b * (1 + rand(-cvar, cvar)));
    }
    this.alive = MAX_P; // força update; custo pequeno
  }

  /* anel de choque expandindo */
  ring(pos, { radius = 3, color = 0xffffff, life = 0.4, y = 0 } = {}) {
    let r = this._ringPool.find(x => !x.userData.busy);
    if (!r) {
      if (this._ringPool.length > 12) return;
      const geo = new THREE.RingGeometry(0.5, 0.62, 40);
      const mat = new THREE.MeshBasicMaterial({ transparent: true, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
      r = new THREE.Mesh(geo, mat);
      r.rotation.x = -Math.PI / 2;
      r.userData.busy = false;
      this.scene.add(r);
      this._ringPool.push(r);
    }
    r.userData.busy = true;
    r.material.color.set(color);
    r.material.opacity = 0.9;
    r.position.set(pos.x, pos.y + y, pos.z);
    r.scale.setScalar(0.1);
    r.userData.t = 0; r.userData.life = life; r.userData.maxR = radius;
    r.visible = true;
  }

  /* luz efêmera (impactos de magia) */
  flash(pos, { color = 0xffffff, intensity = 8, dist = 12, life = 0.3 } = {}) {
    let l = this._lightPool.find(x => !x.userData.busy);
    if (!l) {
      if (this._lightPool.length > 6) return;
      l = new THREE.PointLight(0xffffff, 0, 12);
      l.userData.busy = false;
      this.scene.add(l);
      this._lightPool.push(l);
    }
    l.userData.busy = true;
    l.color.set(color);
    l.position.copy(pos);
    l.intensity = intensity;
    l.distance = dist;
    l.userData.t = 0; l.userData.life = life; l.userData.i0 = intensity;
    l.visible = true;
  }

  update(dt) {
    let any = false;
    for (let i = 0; i < MAX_P; i++) {
      if (this.life[i] <= 0) continue;
      any = true;
      this.life[i] -= dt;
      const i3 = i * 3;
      if (this.life[i] <= 0) {
        this.alpha[i] = 0; this.size[i] = 0;
        continue;
      }
      const dr = Math.max(0, 1 - this.drag[i] * dt);
      this.vel[i3] *= dr;
      this.vel[i3 + 1] = this.vel[i3 + 1] * dr + this.grav[i] * dt;
      this.vel[i3 + 2] *= dr;
      this.pos[i3] += this.vel[i3] * dt;
      this.pos[i3 + 1] += this.vel[i3 + 1] * dt;
      this.pos[i3 + 2] += this.vel[i3 + 2] * dt;
      const f = this.life[i] / this.maxLife[i];
      this.alpha[i] = this.alpha0[i] * f * f;
    }
    if (any) {
      const g = this.points.geometry;
      g.attributes.position.needsUpdate = true;
      g.attributes.alpha.needsUpdate = true;
      g.attributes.size.needsUpdate = true;
      g.attributes.pcolor.needsUpdate = true;
    }
    // anéis
    for (const r of this._ringPool) {
      if (!r.userData.busy) continue;
      r.userData.t += dt;
      const f = r.userData.t / r.userData.life;
      if (f >= 1) { r.userData.busy = false; r.visible = false; continue; }
      r.scale.setScalar(0.1 + r.userData.maxR * f);
      r.material.opacity = 0.9 * (1 - f);
    }
    // luzes
    for (const l of this._lightPool) {
      if (!l.userData.busy) continue;
      l.userData.t += dt;
      const f = l.userData.t / l.userData.life;
      if (f >= 1) { l.userData.busy = false; l.visible = false; continue; }
      l.intensity = l.userData.i0 * (1 - f);
    }
  }
}

/* ---- Helpers de efeitos por elemento ---- */
export const FX = {
