  hurtFlash() {
    const el = $('hurt-vignette');
    el.style.boxShadow = 'inset 0 0 140px rgba(160,20,10,.55)';
    clearTimeout(this._hurtTO);
    this._hurtTO = setTimeout(() => el.style.boxShadow = 'inset 0 0 140px rgba(160,20,10,0)', 250);
  }

  damageNumber(worldPos, text, kind = 'enemy', crit = false) {
    const el = document.createElement('div');
    el.className = `dmgnum ${kind}${crit ? ' crit' : ''}`;
    el.textContent = text;
    el.style.color = kind === 'player' ? '#ff6a5a' : kind === 'heal' ? '#6ae08a' : crit ? '#ffb020' : '#ffd97a';
    $('damage-layer').appendChild(el);
    this.dmgPool.push({ el, pos: worldPos.clone(), t: 0, vy: 60 });
  }

  bubble(worldPos, text) {
    const el = document.createElement('div');
    el.className = 'dmgnum';
    el.style.color = '#e8dcc0';
    el.style.fontSize = '12px';
    el.style.fontStyle = 'italic';
    el.style.background = 'rgba(10,8,5,.7)';
    el.style.padding = '3px 8px';
    el.style.borderRadius = '10px';
    el.textContent = text;
    $('damage-layer').appendChild(el);
    this.bubbles.push({ el, pos: worldPos.clone().add({ x: 0, y: 2.1, z: 0 }), t: 0 });
  }

  updateFloating(dt) {
    const cam = this.game.camera.cam;
    const proj = (p) => {
      const v = p.clone ? p.clone() : { x: p.x, y: p.y, z: p.z };
      // projeta manualmente
      const vec = new (cam.position.constructor)(v.x, v.y, v.z);
      vec.project(cam);
      return [ (vec.x * 0.5 + 0.5) * innerWidth, (-vec.y * 0.5 + 0.5) * innerHeight, vec.z < 1 ];
    };
    for (let i = this.dmgPool.length - 1; i >= 0; i--) {
      const d = this.dmgPool[i];
      d.t += dt;
      d.pos.y += dt * 1.2;
      const [x, y, vis] = proj(d.pos);
      if (!vis || d.t > 1.1) { d.el.remove(); this.dmgPool.splice(i, 1); continue; }
      d.el.style.left = x + 'px';
      d.el.style.top = y + 'px';
      d.el.style.opacity = 1 - d.t / 1.1;
    }
    for (let i = this.bubbles.length - 1; i >= 0; i--) {
      const b = this.bubbles[i];
      b.t += dt;
      const [x, y, vis] = proj(b.pos);
      if (!vis || b.t > 3) { b.el.remove(); this.bubbles.splice(i, 1); continue; }
      b.el.style.left = x + 'px';
      b.el.style.top = y + 'px';
      b.el.style.opacity = b.t < 0.2 ? b.t / 0.2 : b.t > 2.4 ? (3 - b.t) / 0.6 : 1;
    }
  }

  /* =============== DIÁLOGO =============== */
  dialogBox(name, text, options = []) {
    $('dialog').classList.remove('hidden');
    $('d-name').textContent = name;
    $('d-text').textContent = text;
    const opts = $('d-opts');
    opts.innerHTML = '';
    for (const [label, fn] of options) {
      const b = document.createElement('button');
      b.className = 'd-opt';
      b.textContent = label;
      b.onclick = () => { this.game.audio.play('ui'); fn && fn(); };
      opts.appendChild(b);
    }
    if (options.length === 0) {
      const b = document.createElement('button');
      b.className = 'd-opt';
      b.textContent = 'Fechar';
      b.onclick = () => this.closeDialog();
      opts.appendChild(b);
    }
  }
  closeDialog() { $('dialog').classList.add('hidden'); }
  isDialogOpen() { return !$('dialog').classList.contains('hidden'); }

  /* =============== INTERAÇÃO / ALVO / BOSS =============== */
  showInteract(label) {
    const el = $('interact-prompt');
    el.innerHTML = `<b>E</b> — ${label}`;
    el.classList.remove('hidden');
  }
  hideInteract() { $('interact-prompt').classList.add('hidden'); }

  showBossBar(name) {
    $('bossbar').classList.remove('hidden');
    $('boss-name').textContent = name;
    this.bossName = name;
  }
  setBossBar(f) { $('boss-fill').style.transform = `scaleX(${clamp(f, 0, 1)})`; }
  hideBossBar() { $('bossbar').classList.add('hidden'); }

  /* =============== GRIMÓRIO (UI) =============== */
  renderGrimoire() {
    const g = this.game, p = g.player;
    const el = ELEMENTS[p.element];
    const book = $('grimoire-book');
    if (!el) {
      book.innerHTML = `<div class="gpage gleft"><h4>Grimório Selado</h4><p style="color:#4a3a26">O grimório aguarda seu primeiro elemento…<br><i>Complete o Teste do Poder.</i></p></div>`;
      return;
    }
    const left = document.createElement('div');
    left.className = 'gpage gleft';
    const right = document.createElement('div');
    right.className = 'gpage gright';
    const spine = document.createElement('div');
    spine.className = 'gspine';
    left.innerHTML = `<h4>${el.icon} ${el.name} — Página I</h4>`;
    right.innerHTML = `<h4>Grimório de ${p.name || 'Herói'} — Nv ${p.level}</h4>`;
    const unlocked = g.grimoire.unlockedSpells();
    el.spells.forEach((sp, i) => {
      const isUnlocked = unlocked.includes(sp);
      const lvl = p.spellLevels[sp.id] || 1;
      const div = document.createElement('div');
      div.className = 'gspell' + (isUnlocked ? '' : ' locked');
      div.innerHTML = `
        <div class="gs-n">${sp.name}<span class="gs-lv">Nv ${isUnlocked ? lvl : '—'}</span></div>
        <div class="gs-d">${sp.desc}</div>
        <div class="gs-stats">
          <span>Mana ${sp.mana}</span><span>Recarga ${sp.cd}s</span><span>Dano ~${Math.round(sp.dmg * p.spellPower)}</span>
          ${isUnlocked ? '' : '<span style="color:#8a5a2a">🔒 desbloqueia no nível ' + g.grimoire.unlockLevel(sp.unlock) + '</span>'}
        </div>`;
      div.onclick = () => {
        if (!isUnlocked) return;
        book.querySelectorAll('.gspell').forEach(x => x.classList.remove('sel'));
        div.classList.add('sel');
        g.audio.play('page', 0.6);
      };
      (i < 2 ? left : right).appendChild(div);
    });
    const art = document.createElement('div');
    art.className = 'gp-art';
    art.textContent = '✦ ' + el.icon + ' ✦';
    right.appendChild(art);
    book.innerHTML = '';
    book.append(left, spine, right);
  }

  /* =============== INVENTÁRIO (UI) =============== */
  renderInventory() {
    const g = this.game, inv = g.inventory;
    // slots de equipamento
    const slots = [
      ['capacete', '🪖'], ['armadura', '🥼'], ['luvas', '🧤'], ['botas', '🥾'], ['capa', '🧣'], ['acessorio', '📿'], ['arma', '⚔️']
    ];
    const eq = $('equip-slots');
    eq.innerHTML = '';
    for (const [slot, icon] of slots) {
      const div = document.createElement('div');
      div.className = 'eq-slot';
      const cur = g.player.equipment[slot];
      div.innerHTML = `<span>${cur ? ITEMS[cur.id].icon : icon}</span><span class="eq-lbl">${slot}</span>`;
      div.title = cur ? `${ITEMS[cur.id].name} (clique para remover)` : `${slot} (vazio)`;
      div.onclick = () => { if (cur) { g.inventory.unequip(slot); g.audio.play('ui'); } };
      eq.appendChild(div);
    }
    // abas
    const tabs = [
      ['all', 'Tudo'], ['weapon', 'Armas'], ['armor', 'Armaduras'], ['accessory', 'Acessórios'],
      ['consumable', 'Consumíveis'], ['material', 'Materiais'], ['quest', 'Missão'], ['book', 'Livros']
    ];
    const tabBox = $('inv-tabs');
    tabBox.innerHTML = '';
    if (!this.invTab) this.invTab = 'all';
    for (const [id, label] of tabs) {
      const b = document.createElement('button');
      b.className = 'inv-tab' + (this.invTab === id ? ' on' : '');
      b.textContent = label;
      b.onclick = () => { this.invTab = id; this.renderInventory(); g.audio.play('ui', 0.4); };
      tabBox.appendChild(b);
    }
    // grade
    const grid = $('inv-grid');
    grid.innerHTML = '';
    const filtered = inv.items.filter(i => {
      const def = ITEMS[i.id];
      if (!def) return false;
      if (this.invTab === 'all') return true;
      if (this.invTab === 'armor') return def.type === 'armor';
      return def.type === this.invTab;
    });
    for (const item of filtered) {
      const def = ITEMS[item.id];
      const cell = document.createElement('div');
      cell.className = `inv-cell r-${def.rarity}`;
      cell.innerHTML = `<span>${def.icon}</span>${item.qty > 1 ? `<span class="q">${item.qty}</span>` : ''}`;
      cell.title = def.name;
      cell.onclick = () => this.showItemDetail(item.id);
      grid.appendChild(cell);
    }
    if (filtered.length === 0) grid.innerHTML = '<div style="color:#8a7850;font-size:13px;padding:20px">Mochila vazia nesta categoria.</div>';
    $('inv-detail').innerHTML = '<div class="id-desc" style="color:#8a7850">Selecione um item…</div>';
  }

  showItemDetail(id) {
    const g = this.game;
    const def = ITEMS[id];
    if (!def) return;
    const det = $('inv-detail');
    let statHtml = '';
    if (def.stats) {
      statHtml = Object.entries(def.stats).map(([k, v]) => {
        const names = { atk: 'Ataque', def: 'Defesa', hp: 'Vida', mana: 'Mana', spd: 'Velocidade', crit: 'Crítico', magic: 'Poder Mágico' };
        return `+${v} ${names[k] || k}`;
      }).join(' • ');
    }
    const usable = def.type === 'consumable';
    const equippable = !!def.slot;
    det.innerHTML = `
      <div class="id-name">${def.icon} ${def.name} <span style="color:#9a9080;font-size:11px">(${RARITY[def.rarity].name})</span></div>
      <div class="id-desc">${def.desc}</div>
      ${statHtml ? `<div class="id-stat">${statHtml}</div>` : ''}
      <div style="margin-top:8px;display:flex;gap:8px">
        ${equippable ? '<button class="travel-btn" onclick="window.__game.inventory.equipItem(\'' + id + '\')">Equipar</button>' : ''}
        ${usable ? '<button class="travel-btn" onclick="window.__game.inventory.useItem(\'' + id + '\')">Usar</button>' : ''}
        <button class="travel-btn" onclick="window.__game.inventory.sellItem(\'' + id + '\')">Vender (${Math.max(1, Math.floor((def.price || 5) * 0.4))} 🪙)</button>
      </div>`;
    g.audio.play('ui', 0.4);
  }

  /* =============== QUESTS (UI) =============== */
  renderQuests() {
    const g = this.game, q = g.quests;
    const list = $('quests-list');
    list.innerHTML = '';
    const add = (a, done) => {
      const def = QUESTS[a.id || a];
      if (!def) return;
      const div = document.createElement('div');
      div.className = 'q-item';
      const prog = done ? '' : ` <span style="color:#8fb07a">(${q.totalProgress(a)}/${q.totalNeeded(a)})</span>`;
      div.innerHTML = `<div class="q-t ${done ? 'done' : ''}">${done ? '✔' : '📜'} ${def.title}${prog}</div>
        <div class="q-d">${def.desc}</div>
        <div class="q-r">Recompensas: ${def.rewards?.xp || 0} XP${def.rewards?.gold ? `, ${def.rewards.gold} 🪙` : ''}${def.rewards?.items ? ', itens' : ''}</div>`;
      list.appendChild(div);
    };
    if (q.active.length === 0 && q.completed.length === 0) {
      list.innerHTML = '<div style="color:#8a7850;padding:20px">Nenhuma missão ainda. Fale com os moradores!</div>';
    }
    for (const a of q.active) add(a, false);
    for (const id of q.completed) add({ id }, true);
  }

  /* =============== LOJA (UI) =============== */
  renderShop(shopId, npcName) {
    const g = this.game;
    const shop = SHOPS[shopId];
    if (!shop) return;
    $('shop-title').textContent = shop.title;
    const list = $('shop-list');
    list.innerHTML = '';
    for (const id of shop.items) {
      const def = ITEMS[id];
      const row = document.createElement('div');
      row.className = 'shop-item';
      row.innerHTML = `
        <span class="si-ico">${def.icon}</span>
        <span class="si-n">${def.name}<br><span style="font-size:11px;color:#9a9080">${def.desc || ''}</span></span>
        <span class="si-p">${def.price} 🪙</span>
        <button class="buy-btn">Comprar</button>`;
      row.querySelector('button').onclick = () => { g.inventory.buyItem(id); $('shop-gold').textContent = `Ouro: ${g.inventory.gold} 🪙`; };
      list.appendChild(row);
    }
    // vender materiais
    const sellables = g.inventory.items.filter(i => ITEMS[i.id] && ITEMS[i.id].type === 'material');
    for (const s of sellables) {
      const def = ITEMS[s.id];
      const row = document.createElement('div');
      row.className = 'shop-item';
      const price = Math.max(1, Math.floor((def.price || 5) * 0.4));
      row.innerHTML = `<span class="si-ico">${def.icon}</span>
        <span class="si-n">${def.name} x${s.qty}</span>
        <span class="si-p">+${price} 🪙</span>
        <button class="buy-btn">Vender</button>`;
      row.querySelector('button').onclick = () => { g.inventory.sellItem(s.id); this.renderShop(shopId, npcName); };
      list.appendChild(row);
    }
    $('shop-gold').textContent = `Ouro: ${g.inventory.gold} 🪙`;
    this.openPanel('shop');
  }

  refreshGold() {
    const g = this.game;
    $('gold-display').textContent = `🪙 ${g.inventory ? g.inventory.gold : 0}`;
  }

  /* mobile */
  showMobileUI(on) {
    $('mobile-ui').style.display = on ? 'block' : 'none';
  }
}

/* =========================================================
 * Aetheria — Orquestrador principal (Game)
 * ========================================================= */
import * as THREE from '../vendor/three.module.js';
import { clamp, rand, randi, pick, chance, dist, damp } from './core/utils.js';
import { Input } from './core/input.js';
import { CameraCtl } from './core/camera.js';
import { AudioSys } from './audio/audio.js';
import { Particles } from './effects/particles.js';
import { World, REGIONS, DUNGEON_C, CAVE_ENTRANCE } from './world/world.js';
import { DayNight } from './world/daynight.js';
import { Player } from './player/player.js';
import { Combat } from './combat/combat.js';
import { EnemyManager } from './enemies/enemies.js';
import { NPCManager } from './npc/npcs.js';
import { Grimoire } from './grimoire/grimoire.js';
import { Inventory, LootManager, ITEMS, SHOPS } from './inventory/inventory.js';
import { QuestManager } from './quests/quests.js';
import { Story, CHAPTERS } from './story/story.js';
import { BossManager } from './bosses/bosses.js';
import { HUD } from './ui/hud.js';
import { SaveSystem } from './save/save.js';
import { SpellCaster } from './magic/spells.js';

export class Game {
  constructor(_THREE, prog) {
    this.THREE = THREE;
    this.prog = prog;

    /* ---------- renderizador ---------- */
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    this.renderer.setSize(innerWidth, innerHeight);
    this.renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.05;
    document.getElementById('app').appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(60, innerWidth / innerHeight, 0.1, 1500);
    this.camCtl = new CameraCtl(this.camera);
    this.camera.position.set(0, 8, 14);

    addEventListener('resize', () => {
      this.camera.aspect = innerWidth / innerHeight;
      this.camera.updateProjectionMatrix();
      this.renderer.setSize(innerWidth, innerHeight);
    });

    /* ---------- configurações ---------- */
    this.settings = { music: 55, sfx: 70, sens: 100, camdist: 75, cammax: 140, invert: false, shadows: 2, particles: 2, fps: true };
    this.paused = true;
    this.playing = false;
    this.clock = new THREE.Clock();
    this.autosaveT = 30;

    /* ---------- sistemas ---------- */
    this.input = new Input();
    this.audio = new AudioSys();
    this.fx = new Particles(this.scene);
    this.world = new World(this.scene);
    this.daynight = new DayNight(this.scene);
    this.player = new Player(this);
    this.player.recalc();
    this.combat = new Combat(this);
    this.enemies = new EnemyManager(this);
    this.npcs = new NPCManager(this);
    this.grimoire = new Grimoire(this);
    this.inventory = new Inventory(this);
    this.loot = new LootManager(this);
    this.quests = new QuestManager(this);
    this.story = new Story(this);
    this.bosses = new BossManager(this);
    this.hud = new HUD(this);
    this.save = new SaveSystem(this);

    /* filas de magia/projéteis */
    this.spellProjectiles = [];
    this.enemyProjectiles = [];
    this.effectQueue = [];
    this.cityGatePos = { x: 0, z: -195 };

    this._scanT = 0;
    this._regionT = 0;
    this._eventT = rand(50, 100);
    this._lastT = performance.now();
    this.errShown = false;

    this.setupInteractables();
    this.setupSpawnZones();

    prog && prog(90, 'Acordando os sistemas…');
    this.loop();
  }

  /* ================= INTERAÇÕES DO MUNDO ================= */
  setupInteractables() {
    const w = this.world;
    // cristal do castelo
    w.interactables.push({
      pos: w.crystalPos.clone(), r: 3,
      label: 'Colocar a mão no cristal', icon: '🔮',
      action: () => this.story.onCrystalInteract(),
      enabled: () => true
    });
    // fonte da vila
    w.interactables.push({
      pos: new THREE.Vector3(0, w.fountainPos.y, 0), r: 3.4,
      label: 'Descansar na fonte', icon: '⛲',
      action: () => {
        this.player.hp = this.player.maxHp;
        this.player.mana = this.player.maxMana;
        this.audio.play('heal');
        this.hud.toast('Você descansou na fonte. ❤️💚');
      },
      cd: 30
    });
    // baús
    for (const chest of w.chests) {
      w.interactables.push({
        pos: chest.pos.clone(), r: 2.4,
        label: () => chest.opened ? 'Baú vazio' : 'Abrir baú', icon: '🎁',
        action: () => {
          if (chest.opened) return;
          chest.opened = true;
          this.audio.play('chest');
          if (chest.lid) chest.lid.rotation.x = -1.1;
          this.fx.spawn(chest.pos.clone().add(new THREE.Vector3(0, 0.8, 0)), { count: 18, color: 0xf5d97a, speed: 2.5, life: 0.8, size: 5, gravity: 2 });
          // conteúdo por região
          const n = randi(1, 3);
          for (let i = 0; i < n; i++) {
            const roll = Math.random();
            let id = 'potion_hp';
            if (roll > 0.7) id = pick(['sword_iron', 'helm_iron', 'chest_chain', 'amulet_mana', 'boots_swift']);
            else if (roll > 0.45) id = 'potion_mp';
            else if (roll > 0.3) id = pick(['mat_ore', 'mat_crystal', 'mat_herb']);
            this.loot.spawnPickup(id, chest.pos, this);
          }
          const gold = randi(15, 60);
          this.inventory.addGold(gold);
          this.hud.toast(`Baú aberto! +${gold} 🪙`);
          this.fx.ring(chest.pos, { radius: 1.5, color: 0xf5d97a, life: 0.5 });
        }
      });
    }
    // ervas
    for (const herb of w.herbs) {
      w.interactables.push({
        pos: herb.pos.clone(), r: 2,
        label: 'Coletar Erva Curativa', icon: '🌿',
        action: () => {
          if (herb.taken) return;
          herb.taken = true;
          herb.mesh.visible = false;
          this.inventory.addItem('mat_herb');
          this.audio.play('potion', 0.6);
          this.fx.spawn(herb.pos, { count: 8, color: 0x6ae08a, speed: 1.5, life: 0.5, size: 4, upBias: 1 });
        }
      });
    }
    // entrada da caverna (masmorra)
    w.interactables.push({
      pos: new THREE.Vector3(CAVE_ENTRANCE.x, w.terrainHeight(CAVE_ENTRANCE.x, CAVE_ENTRANCE.z) + 2, CAVE_ENTRANCE.z), r: 4,
      label: 'Entrar na Caverna de Umbra', icon: '🕳️',
      action: () => {
        const p = this.player.root.position;
        p.set(DUNGEON_C.x, this.world.terrainHeight(DUNGEON_C.x, DUNGEON_C.z - 30) + 0.2, DUNGEON_C.z - 30);
        this.fx.ring(p, { radius: 2, color: 0x8a5aff, life: 0.6 });
        this.audio.play('door');
        this.hud.toast('Você adentra a escuridão da caverna… 🕯️');
        this.audio.setMood('dungeon');
        // o Rei desperta
        if (!this._dungeonBossSpawned) {
          this._dungeonBossSpawned = true;
          setTimeout(() => {
            const king = this.enemies.spawn('goblinKing', DUNGEON_C.x, DUNGEON_C.z, { bossBar: true });
            this.hud.tutorial('O Rei Goblin Gronnak desperta! <b>Esquive (Espaço)</b> dos golpes pesados e castigue com magia.', 7);
          }, 2500);
        }
      }
    });
    // saída da caverna
    w.interactables.push({
      pos: new THREE.Vector3(DUNGEON_C.x, 4, DUNGEON_C.z - 30), r: 4,
      label: 'Sair da caverna', icon: '🌅',
      action: () => {
        const p = this.player.root.position;
        p.set(CAVE_ENTRANCE.x + 3, this.world.terrainHeight(CAVE_ENTRANCE.x + 3, CAVE_ENTRANCE.z) + 0.2, CAVE_ENTRANCE.z + 3);
        this.audio.play('door');
      }
    });
  }

  setupSpawnZones() {
    const E = this.enemies;
    E.addZone({ x: 170, z: 170, r: 42, max: 5, interval: 7, activeRange: 130, type: () => pick(['goblin', 'goblin', 'goblinWarrior', 'goblinArcher']), ranks: ['E', 'E', 'D'] });
    E.addZone({ x: 260, z: -60, r: 70, max: 5, interval: 9, activeRange: 130, type: 'wolf' });
    E.addZone({ x: 400, z: 240, r: 60, max: 5, interval: 9, activeRange: 130, type: 'slime' });
    E.addZone({ x: -280, z: 40, r: 50, max: 4, interval: 12, activeRange: 130, type: 'skeleton' });
    E.addZone({ x: -380, z: -220, r: 70, max: 4, interval: 10, activeRange: 130, type: 'wolf', ranks: ['E', 'D'] });
    E.addZone({ x: -400, z: 280, r: 60, max: 4, interval: 12, activeRange: 130, type: 'slime', ranks: ['D', 'C'] });
    E.addZone({ x: 500, z: -320, r: 80, max: 6, interval: 8, activeRange: 140, type: () => pick(['goblinWarrior', 'goblinElite', 'goblinMage']), ranks: ['C', 'B', 'B'] });
    E.addZone({ x: -140, z: -430, r: 80, max: 4, interval: 10, activeRange: 130, type: 'wolf', ranks: ['D', 'C'] });
  }

  /* ================= INÍCIO ================= */
  startGame(load) {
    this.playing = true;
    this.paused = false;
    this.audio.ensure();
    this.audio.setVolumes(this.settings.music / 100, this.settings.sfx / 100);
    if (load) {
      const ok = this.save.loadGame();
      if (!ok) this.hud.toast('Save não encontrado — iniciando novo jogo.');
    }
    this.hud.hideMainMenu();
    this.hud.refreshGold();
    this.hud.refreshHotbar();
    this.hud.showMobileUI(this.input.isTouch);
    this.camCtl.targetDist = this.settings.camdist / 10;
    this.camCtl.sensitivity = this.settings.sens / 100;
    this.camCtl.invertY = this.settings.invert;
    this.camCtl.maxDist = this.settings.cammax / 10;
    this.daynight.setShadowQuality(this.settings.shadows);
    if (!load) {
      this.inventory.addStarter();
      this.story.start();
      this.save.saveGame();
    } else {
      this.hud.announce('BEM-VINDO DE VOLTA', CHAPTERS[Math.min(this.story.chapter, CHAPTERS.length - 1)], 3);
    }
  }

  /* ================= LOOP ================= */
  loop() {
    requestAnimationFrame(() => this.loop());
    const now = performance.now();
    let dt = (now - this._lastT) / 1000;
    this._lastT = now;
    dt = clamp(dt, 0, 0.05);

    try {
      if (this.playing && !this.paused && !this.errShown) {
        this.update(dt);
      }
      this.renderer.render(this.scene, this.camera);
    } catch (err) {
      console.error('Erro no loop do jogo:', err);
      this.showError(err);
    }
    this.input.endFrame();
  }

  update(dt) {
    const p = this.player;

    /* câmera sempre responde */
    this.camCtl.update(dt, this);

    /* teclas de interface */
    if (this.input.wasPressed('Escape')) {
      if (this.hud.isDialogOpen()) this.hud.closeDialog();
      else if (this.hud.isPanelOpen()) this.hud.closeAllPanels();
      else this.hud.togglePause(true);
    }
    if (this.input.wasPressed('KeyG') && this.grimoire.visible) this.grimoire.toggle();
    if (this.input.wasPressed('KeyI')) this.hud.togglePanel('inventory');
    if (this.input.wasPressed('KeyM')) this.hud.togglePanel('map');
    if (this.input.wasPressed('KeyJ')) this.hud.togglePanel('quests');

    /* mundo */
    this.daynight.update(dt, this);
    this.world.update(dt, this.daynight.isNight, this);

    /* jogador + combate */
    p.update(dt, this.input);
    this.combat.updateLock(dt);

    /* inimigos / NPCs */
    this.enemies.update(dt);
    this.npcs.update(dt);

    /* magias */
    for (let i = this.spellProjectiles.length - 1; i >= 0; i--) {
      const pr = this.spellProjectiles[i];
      pr.update(dt, this);
      if (pr.dead) this.spellProjectiles.splice(i, 1);
    }
    for (let i = this.enemyProjectiles.length - 1; i >= 0; i--) {
      const pr = this.enemyProjectiles[i];
      pr.update(dt, this);
      if (pr.dead) this.enemyProjectiles.splice(i, 1);
    }
    SpellCaster.updateEffects(dt, this);
    this.fx.update(dt);
    this.grimoire.update(dt);
    this.bosses.update(dt);
    this.loot.update(dt);
    this.story.update(dt);

    /* interação mais próxima */
    this._scanT -= dt;
    if (this._scanT <= 0) {
      this._scanT = 0.12;
      this.scanInteraction();
      this.scanRegions(dt);
    }

    /* eventos aleatórios */
    this._eventT -= dt;
    if (this._eventT <= 0) {
      this._eventT = rand(70, 140);
      this.randomEvent();
    }

    /* HUD */
    this.hud.update(dt);
    this.hud.refreshGold();

    /* música */
    this.audio.updateMusic();

    /* autosave */
    this.autosaveT -= dt;
    if (this.autosaveT <= 0) {
      this.autosaveT = 30;
      this.save.saveGame();
    }
  }

  /* ================= INTERAÇÃO ================= */
  scanInteraction() {
    const p = this.player;
    if (p.dead) { this.hud.hideInteract(); return; }
    const pp = p.root.position;

    // NPC mais próximo
    const npc = this.npcs.nearest(pp, 3.4);
    let best = null, bestLabel = '', bestAction = null, bestIcon = '';
    if (npc) {
      best = { type: 'npc', npc };
      bestLabel = `Falar com ${npc.name}`;
      bestAction = () => this.talkToNPC(npc);
      bestIcon = '💬';
    }
    // interativos do mundo
    for (const it of this.world.interactables) {
      const label = typeof it.label === 'function' ? it.label() : it.label;
      if (label === 'Baú vazio') continue;
      const d = dist(pp.x, pp.z, it.pos.x, it.pos.z);
      if (d < (it.r || 2.5) && d < (best ? 3.4 : 99)) {
        if (it.cd && it._cdT > 0) continue;
        best = { type: 'world', it };
        bestLabel = label;
        bestAction = () => {
          if (it.cd) it._cdT = it.cd;
          it.action(this);
        };
        bestIcon = it.icon || '✋';
      }
    }
    // ervas tomadas
    if (best && best.type === 'world' && best.it.label === 'Coletar Erva Curativa') {
      const herb = this.world.herbs.find(h => h.pos === best.it.pos);
      if (herb && herb.taken) { best = null; }
    }

    if (best) {
      this.hud.showInteract(`${bestIcon} ${bestLabel}`);
      if (this.input.wasPressed('KeyE') && !this.hud.isPanelOpen()) bestAction();
    } else {
      this.hud.hideInteract();
    }
    // decrementar cds de interação
    for (const it of this.world.interactables) {
      if (it._cdT > 0) it._cdT -= 0.12;
    }
  }

  talkToNPC(npc) {
    const g = this;
    const isNight = this.daynight.isNight;
    const lines = {
      elder: 'Que os Antigos te guardem, jovem. O castelo espera pelos candidatos ao Teste do Poder.',
      blacksmith: 'Aço honesto para heróis honestos! Dê uma olhada.',
      merchant: 'Poções fresquinhas! Compre duas, leve… bem, compre duas.',
      innkeeper: 'Sente-se, viajante! Uma caneca e uma história boa curam qualquer ferida.',
      priest: 'A luz te acompanhe. As eras escuras se aproximam — prepare-se.',
      farmer: 'A terra é generosa… quando não vêm goblins comer a colheita!',
      arion: 'Ah, o portador do novo elemento. O cristal raramente erra.',
      guard1: 'Mantenha os olhos abertos. Dizem que o acampamento goblin cresce.',
      guard2: 'A cidadela está segura… por enquanto.',
      kid1: 'Você lutou contra goblins?! Conte tudo!',
      kid2: 'Quando eu crescer, quero um grimório também!',
      villager1: 'Bom dia! Que a colheita seja generosa.',
      villager2: 'Cuidado no pântano ao sudeste. Ele engole os distraídos.',
      captain: 'Mantenha-se firme, soldado… digo, aventureiro.'
    };
    let text = lines[npc.id] || '…';
    if (isNight && !npc.def.kid) text = 'Já é tarde. Deveria estar em casa…';

    const options = [];
    if (npc.def.shop) {
      options.push(['🛒 Comprar / Vender', () => { this.hud.closeDialog(); this.hud.renderShop(npc.def.shop, npc.name); }]);
    }
    options.push(['Até logo', () => this.hud.closeDialog()]);
    this.hud.dialogBox(`${npc.name} — ${npc.role}`, text, options);
    this.quests.onTalk(npc.id);
  }

  /* ================= REGIÕES ================= */
  scanRegions(dt) {
    this._regionT -= dt;
    if (this._regionT > 0) return;
    this._regionT = 0.5;
    const r = this.world.regionAt(this.player.root.position.x, this.player.root.position.z);
    if (r && !r.discovered) {
      r.discovered = true;
      this.hud.announce(r.name.toUpperCase(), '📍 Nova região descoberta', 2.5);
      this.audio.play('quest', 0.7);
      this.quests.onDiscover(r.id);
      this.player.gainXP(50);
      this.save.saveGame();
    }
  }

  /* ================= EVENTOS ALEATÓRIOS ================= */
  randomEvent() {
    if (this.story.invasionActive) return;
    const region = this.world.regionAt(this.player.root.position.x, this.player.root.position.z);
    const safe = region && region.safe;
    const p = this.player.root.position;
    const roll = Math.random();
    const lvl = this.player.level;

    if (!safe && roll < 0.45) {
      // emboscada
      this.hud.toast('Você sente que está sendo observado… 👀');
      const kind = region && region.id === 'volcano' || region && region.id === 'snow' ? 'wolf' : chance(0.5) ? 'bandit' : 'goblin';
      const rank = lvl >= 6 ? 'C' : lvl >= 3 ? 'D' : 'E';
      for (let i = 0; i < 3; i++) {
        const a = rand(0, Math.PI * 2);
        this.enemies.spawn(kind, p.x + Math.cos(a) * 22, p.z + Math.sin(a) * 22, { rank });
      }
      this.audio.play('goblin', 0.8);
    } else if (roll < 0.6 && !safe) {
      // tesouro
      this.hud.toast('Algo brilha no chão… ✨');
      this.loot.spawnPickup(pick(['potion_hp', 'mat_crystal', 'scroll_tp', 'potion_mp']), p, this);
    } else if (roll < 0.75) {
      // viajante pedindo ajuda
      this.hud.toast('Um viajante passa apressado: "Goblins na estrada! Cuidado!" 🐴');
    } else if (roll < 0.85) {
      // evento mágico
      this.hud.toast('Uma aurora arcanas dança no céu… 🌌');
      this.fx.spawn(p.clone().add(new THREE.Vector3(0, 12, 0)), { count: 30, color: 0x9a7aff, speed: 2, life: 2, size: 6, gravity: -0.5, alpha: 0.5 });
      this.player.gainXP(30);
    } else {
      // mercador itinerante
      this.hud.toast('Um mercador itinerante oferece especiarias. (+5 🪙 de sorte)');
      this.inventory.addGold(5);
    }
  }

  /* ================= ERRO ================= */
  showError(err) {
    if (this.errShown) return;
    this.errShown = true;
    try {
      const ov = document.getElementById('error-overlay');
      document.getElementById('error-msg').textContent = 'Ocorreu um erro durante o jogo. O mundo será recarregado.';
      document.getElementById('error-detail').textContent = String(err && err.stack || err);
      ov.style.display = 'flex';
    } catch (e) {}
  }
}

