input.content:
import { chromium } from 'playwright-core';

const EXE = '/usr/bin/chromium';
const browser = await chromium.launch({
  executablePath: EXE,
  headless: true,
  args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--window-size=1280,800']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://localhost:8099/', { waitUntil: 'load', timeout: 30000 });
// espera menu
try {
  await page.waitForSelector('#mainmenu:not(.hidden)', { timeout: 20000 });
  console.log('MENU OK');
} catch { console.log('MENU FAIL — loading pode ter travado'); }
await page.screenshot({ path: '/tmp/opencode/shot1_menu.jpg', quality: 70, type: 'jpeg' });

// inicia novo jogo
await page.click('#mm-new');
await page.waitForTimeout(4000);
await page.screenshot({ path: '/tmp/opencode/shot2_game.jpg', quality: 70, type: 'jpeg' });

// estado do jogo
const state = await page.evaluate(() => {
  const g = window.__game;
  if (!g) return { error: 'no game' };
  return {
    playing: g.playing, paused: g.paused,
    playerPos: g.player.root.position.toArray().map(v => +v.toFixed(1)),
    hp: g.player.hp, fps: document.getElementById('fps-counter').textContent,
    npcs: g.npcs.npcs.length, enemies: g.enemies.list.length,
    quest: document.getElementById('qt-title').textContent
  };
});
console.log('STATE:', JSON.stringify(state));

// anda para frente por 2s
await page.keyboard.down('KeyW');
await page.waitForTimeout(2000);
await page.keyboard.up('KeyW');
// gira câmera com botão direito
await page.mouse.move(640, 400);
await page.mouse.down({ button: 'right' });
await page.mouse.move(500, 380, { steps: 5 });
await page.mouse.up({ button: 'right' });
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/shot3_moved.jpg', quality: 70, type: 'jpeg' });

const state2 = await page.evaluate(() => {
  const g = window.__game;
  return { pos: g.player.root.position.toArray().map(v => +v.toFixed(1)), fps: document.getElementById('fps-counter').textContent };
});
console.log('STATE2:', JSON.stringify(state2));

console.log('ERRORS:', errors.length ? errors.slice(0, 12).join('\n') : 'nenhum');
await browser.close();

