5: <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
6: <title>Crônicas de Aetheria — RPG 3D</title>
7: <style>
8: :root{
9:   --gold:#d8b45a; --gold2:#f5d97a; --parch:#e8d9b0; --ink:#2a2018;
10:   --blood:#a52a2a; --hp:#c0392b; --mana:#2e86c1; --stam:#27ae60; --xp:#c9a227;
11:   --panel:rgba(12,9,7,.88); --border:rgba(216,180,90,.55);
12: }
13: *{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
14: html,body{width:100%;height:100%;overflow:hidden;background:#050403;font-family:Georgia,'Times New Roman',serif;color:#e8dcc0}
15: #app{position:fixed;inset:0}
16: canvas{display:block}
17: .hidden{display:none !important}
18: button{font-family:inherit;cursor:pointer}
19: 
20: /* ============ LOADING / ERROR ============ */
21: #loading{position:fixed;inset:0;background:radial-gradient(ellipse at center,#1a1208 0%,#050403 75%);display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:200}
22: #loading h1{font-size:42px;letter-spacing:6px;color:var(--gold2);text-shadow:0 0 30px rgba(216,180,90,.4)}
23: #loading .sub{margin-top:8px;color:#a89060;letter-spacing:3px;font-style:italic}
24: #loadbar{margin-top:30px;width:min(420px,70vw);height:10px;border:1px solid var(--border);border-radius:5px;overflow:hidden;background:#0a0806}
25: #loadbar>div{height:100%;width:0%;background:linear-gradient(90deg,#8a6a20,#f5d97a);transition:width .3s}
26: #loadmsg{margin-top:10px;font-size:12px;color:#8a7850;letter-spacing:2px}
27: #error-overlay{position:fixed;inset:0;background:rgba(5,4,3,.96);z-index:300;display:none;align-items:center;justify-content:center}
28: #error-overlay .box{max-width:560px;padding:30px;border:2px solid #a52a2a;background:#160b08;border-radius:10px;text-align:center}
29: #error-overlay h2{color:#e88;font-size:24px;margin-bottom:12px}
30: #error-overlay p{color:#cba;font-size:14px;line-height:1.6;margin-bottom:14px}
31: #error-overlay pre{text-align:left;font-size:11px;color:#a88;background:#000;padding:10px;border-radius:6px;max-height:120px;overflow:auto;white-space:pre-wrap}
32: #error-overlay button{margin-top:10px;padding:10px 26px;background:#3a1a12;color:#eaa;border:1px solid #a52a2a;border-radius:6px;font-size:14px}
33: 
34: /* ============ MAIN MENU ============ */
35: #mainmenu{position:fixed;inset:0;z-index:150;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at 50% 30%,#2a1c0e 0%,#0a0705 70%)}
36: #mainmenu .inner{text-align:center}
37: #mainmenu h1{font-size:52px;letter-spacing:8px;color:var(--gold2);text-shadow:0 0 40px rgba(245,217,122,.35),0 2px 0 #3a2a08}
38: #mainmenu h2{font-size:15px;letter-spacing:5px;color:#a89060;margin-top:6px;font-weight:normal;font-style:italic}
39: #mm-buttons{margin-top:44px;display:flex;flex-direction:column;gap:12px;align-items:center}
40: .mm-btn{width:280px;padding:13px;background:linear-gradient(180deg,rgba(58,44,20,.9),rgba(30,22,10,.9));border:1px solid var(--border);border-radius:6px;color:var(--parch);font-size:17px;letter-spacing:3px;transition:all .15s}
41: .mm-btn:hover{background:linear-gradient(180deg,rgba(90,68,28,.95),rgba(50,36,16,.95));color:#fff;box-shadow:0 0 18px rgba(216,180,90,.25)}
42: .mm-btn:disabled{opacity:.35;cursor:not-allowed}
43: #mm-version{margin-top:30px;font-size:11px;color:#6a5a38;letter-spacing:2px}
44: 
45: /* ============ HUD ============ */
46: #hud{position:fixed;inset:0;pointer-events:none;z-index:50}
47: #hud>*{pointer-events:none}
48: 
49: /* vitals top-left */
50: #vitals{position:absolute;top:16px;left:16px;width:270px}
51: #vitals .row{display:flex;align-items:center;gap:8px;margin-bottom:5px}
52: .lvl-orb{width:44px;height:44px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#5a4416,#241a06);border:2px solid var(--gold);display:flex;align-items:center;justify-content:center;font-size:19px;color:var(--gold2);font-weight:bold;flex-shrink:0;text-shadow:0 0 8px rgba(245,217,122,.6)}
53: .barcol{flex:1}
54: .bar{position:relative;height:15px;background:rgba(0,0,0,.65);border:1px solid rgba(216,180,90,.4);border-radius:3px;overflow:hidden}
55: .bar+.bar{margin-top:4px}
56: .bar>.fill{position:absolute;inset:0;transform-origin:left;border-radius:2px}
57: .bar.hp>.fill{background:linear-gradient(180deg,#e05545,#8a1e12)}
58: .bar.mp>.fill{background:linear-gradient(180deg,#4aa0e0,#1a4a7a)}
59: .bar.sp>.fill{background:linear-gradient(180deg,#4ac070,#1a6a35)}
60: .bar>.txt{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:10px;color:#fff;text-shadow:0 1px 2px #000;letter-spacing:1px}
61: #xpbar{height:5px;margin-top:5px}
62: #xpbar>.fill{background:linear-gradient(90deg,#8a6a20,#f5d97a)}
63: #elem-badge{display:flex;align-items:center;gap:8px;margin-top:7px;font-size:13px;letter-spacing:2px}
64: #elem-badge .ico{font-size:18px}
65: 
66: /* minimap top-right */
67: #minimap-wrap{position:absolute;top:16px;right:16px;text-align:center}
68: #minimap{width:180px;height:180px;border:2px solid var(--border);border-radius:50%;background:#1a140a;box-shadow:0 0 14px rgba(0,0,0,.7)}
69: #clock{margin-top:4px;font-size:12px;color:var(--parch);letter-spacing:2px;text-shadow:0 1px 3px #000}
70: #gold-display{position:absolute;top:210px;right:16px;font-size:15px;color:var(--gold2);text-shadow:0 1px 3px #000;letter-spacing:1px}
71: 
72: /* quest tracker */
73: #quest-tracker{position:absolute;top:130px;left:16px;max-width:290px;background:linear-gradient(180deg,rgba(20,15,8,.75),rgba(12,9,5,.75));border:1px solid var(--border);border-radius:6px;padding:10px 12px}
74: #quest-tracker .qt-title{font-size:13px;color:var(--gold2);letter-spacing:2px;margin-bottom:4px}
75: #quest-tracker .qt-obj{font-size:12px;color:#d8ccae;line-height:1.45}
76: #quest-tracker .qt-dist{font-size:11px;color:#8fb07a;margin-top:3px}
77: 
78: /* hotbar */
79: #hotbar{position:absolute;bottom:18px;left:50%;transform:translateX(-50%);display:flex;gap:7px}
80: .hslot{width:56px;height:56px;background:linear-gradient(180deg,rgba(40,30,14,.9),rgba(18,13,7,.9));border:2px solid rgba(216,180,90,.45);border-radius:6px;position:relative;display:flex;align-items:center;justify-content:center;font-size:24px}
81: .hslot .key{position:absolute;top:2px;left:5px;font-size:10px;color:var(--gold2);text-shadow:0 1px 2px #000}
82: .hslot .cost{position:absolute;bottom:2px;right:5px;font-size:9px;color:#6ab4e8}
83: .hslot .cd{position:absolute;inset:0;background:rgba(0,0,0,.72);transform-origin:bottom;border-radius:4px}
84: .hslot .qty{position:absolute;bottom:2px;left:5px;font-size:10px;color:#fff;text-shadow:0 1px 2px #000}
85: .hslot.locked{opacity:.32;filter:grayscale(1)}
86: .hslot.empty{opacity:.5}
87: .hslot .nm{position:absolute;bottom:-16px;left:50%;transform:translateX(-50%);font-size:9px;color:#b8a878;white-space:nowrap;letter-spacing:.5px}
88: 
89: /* crosshair & interact */
90: #crosshair{position:absolute;top:50%;left:50%;width:6px;height:6px;margin:-3px;border:1px solid rgba(255,255,255,.7);border-radius:50%;box-shadow:0 0 4px #000;opacity:.85}
91: #interact-prompt{position:absolute;top:58%;left:50%;transform:translateX(-50%);background:rgba(10,8,5,.85);border:1px solid var(--border);padding:7px 16px;border-radius:5px;font-size:14px;letter-spacing:1px;color:var(--parch)}
92: #interact-prompt b{color:var(--gold2)}
93: 
94: /* boss bar */
95: #bossbar{position:absolute;top:34px;left:50%;transform:translateX(-50%);width:min(560px,70vw);text-align:center}
96: #bossbar .bname{font-size:17px;letter-spacing:4px;color:#f0c8a0;text-shadow:0 0 12px rgba(200,80,40,.8),0 2px 3px #000;margin-bottom:5px}
97: #bossbar .bbar{height:14px;background:rgba(0,0,0,.75);border:1px solid #7a3a20;border-radius:3px;overflow:hidden}
98: #bossbar .bfill{height:100%;background:linear-gradient(180deg,#e06030,#7a1a08);transform-origin:left}
99: 
100: /* announcements */
101: #announce{position:absolute;top:24%;left:0;right:0;text-align:center;pointer-events:none;opacity:0;transition:opacity .5s}
102: #announce .a-big{font-size:52px;letter-spacing:10px;color:var(--gold2);text-shadow:0 0 34px rgba(245,217,122,.7),0 3px 0 #2a1c04}
103: #announce .a-small{font-size:18px;letter-spacing:6px;color:#d8ccae;margin-top:8px;text-shadow:0 2px 4px #000}
104: #announce .a-line{width:220px;height:1px;background:linear-gradient(90deg,transparent,var(--gold),transparent);margin:12px auto}
105: #tut-hint{position:absolute;bottom:110px;left:50%;transform:translateX(-50%);background:rgba(10,8,5,.85);border:1px solid var(--border);border-radius:6px;padding:9px 20px;font-size:14px;letter-spacing:1px;color:#e8dcc0;text-align:center;transition:opacity .4s}
106: #tut-hint b{color:var(--gold2)}
107: 
108: /* dialog */
109: #dialog{position:absolute;bottom:96px;left:50%;transform:translateX(-50%);width:min(620px,88vw);background:linear-gradient(180deg,rgba(24,18,10,.95),rgba(14,10,6,.95));border:2px solid var(--border);border-radius:8px;padding:16px 20px;pointer-events:auto}
110: #dialog .d-name{font-size:16px;color:var(--gold2);letter-spacing:3px;margin-bottom:8px}
111: #dialog .d-text{font-size:15px;line-height:1.55;color:#e8dcc0;min-height:44px}
112: #dialog .d-opts{margin-top:10px;display:flex;flex-direction:column;gap:5px}
113: #dialog .d-opt{text-align:left;padding:7px 12px;background:rgba(60,46,20,.5);border:1px solid rgba(216,180,90,.3);border-radius:4px;color:var(--parch);font-size:14px}
114: #dialog .d-opt:hover{background:rgba(90,68,28,.7);color:#fff}
115: 
116: /* damage numbers */
117: .dmgnum{position:absolute;font-size:16px;font-weight:bold;text-shadow:0 1px 3px #000;pointer-events:none;white-space:nowrap;transform:translate(-50%,-50%)}
118: .dmgnum.crit{font-size:22px}
119: .dmgnum.player{color:#ff6a5a}.dmgnum.enemy{color:#ffd97a}.dmgnum.heal{color:#6ae08a}
120: 
121: /* toasts */
122: #toasts{position:absolute;top:96px;right:196px;display:flex;flex-direction:column;gap:6px;align-items:flex-end}
123: .toast{background:rgba(12,9,5,.9);border:1px solid var(--border);border-left:3px solid var(--gold);border-radius:4px;padding:8px 14px;font-size:13px;color:var(--parch);animation:toastIn .3s;max-width:320px}
124: @keyframes toastIn{from{transform:translateX(30px);opacity:0}to{transform:none;opacity:1}}
125: 
126: /* target frame */
127: #target-frame{position:absolute;top:110px;left:50%;transform:translateX(-50%);width:230px;background:rgba(12,9,5,.7);border:1px solid rgba(180,80,60,.6);border-radius:6px;padding:6px 10px;text-align:center}
128: #target-frame .tname{font-size:13px;color:#f0c8a0;letter-spacing:2px}
129: #target-frame .tbar{height:9px;background:#000;border:1px solid #5a2a18;border-radius:2px;margin-top:4px;overflow:hidden}
130: #target-frame .tfill{height:100%;background:linear-gradient(180deg,#d05540,#7a1808);transform-origin:left}
131: #target-frame .trank{font-size:11px;color:#c9a227;margin-top:2px}
132: 
133: /* ============ PANELS ============ */
134: .panel{position:fixed;inset:0;z-index:110;display:none;align-items:center;justify-content:center;background:rgba(4,3,2,.72);backdrop-filter:blur(3px)}
135: .panel.open{display:flex}
136: .panel .pbox{background:linear-gradient(180deg,#241a0e,#140e07);border:2px solid var(--border);border-radius:10px;padding:24px;max-width:min(860px,92vw);max-height:88vh;overflow:auto;pointer-events:auto;box-shadow:0 10px 60px rgba(0,0,0,.8)}
137: .panel h3{color:var(--gold2);letter-spacing:4px;font-size:20px;margin-bottom:16px;text-align:center}
138: .pclose{float:right;background:none;border:1px solid var(--border);color:var(--parch);border-radius:4px;padding:3px 10px;font-size:12px}
139: 
140: /* settings */
141: .set-row{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:12px;min-width:420px}
142: .set-row label{font-size:14px;color:var(--parch);letter-spacing:1px}
143: .set-row input[type=range]{width:200px;accent-color:#c9a227}
144: .set-row .val{font-size:12px;color:var(--gold2);width:42px;text-align:right}
145: .set-row select,.set-row input[type=checkbox]{accent-color:#c9a227}
146: .btnrow{display:flex;gap:10px;justify-content:center;margin-top:18px}
147: 
148: /* grimoire */
149: #grimoire-book{display:flex;gap:2px;min-width:680px;max-width:92vw}
150: .gpage{flex:1;background:linear-gradient(160deg,#e8d9b0,#cfc094);color:var(--ink);padding:22px;border-radius:3px;min-height:440px;position:relative;box-shadow:inset 0 0 40px rgba(120,90,40,.25)}
151: .gpage h4{font-size:15px;letter-spacing:2px;border-bottom:1px solid rgba(42,32,24,.4);padding-bottom:8px;margin-bottom:12px;text-align:center}
152: .gspell{padding:10px;border-bottom:1px dashed rgba(42,32,24,.3);cursor:pointer;transition:background .15s}
153: .gspell:hover{background:rgba(42,32,24,.08)}
154: .gspell.sel{background:rgba(160,120,40,.18)}
155: .gspell .gs-n{font-size:15px;font-weight:bold}
156: .gspell .gs-lv{float:right;font-size:11px;color:#7a5a20}
157: .gspell .gs-d{font-size:12px;color:#4a3a26;margin-top:3px;line-height:1.4}
158: .gspell .gs-stats{font-size:11px;color:#6a5432;margin-top:4px;display:flex;gap:12px;flex-wrap:wrap}
159: .gspell.locked{opacity:.45;cursor:default}
160: .gspell.locked .gs-n::after{content:" 🔒";font-size:11px}
161: .gpage .gp-art{position:absolute;bottom:16px;left:0;right:0;text-align:center;font-size:34px;opacity:.5;filter:sepia(1)}
162: .gpage.gleft{border-radius:6px 2px 2px 6px}
163: .gpage.gright{border-radius:2px 6px 6px 2px;background:linear-gradient(200deg,#e8d9b0,#cfc094)}
164: .gspine{width:14px;background:linear-gradient(90deg,#3a2810,#5a4020,#3a2810);border-radius:2px}
165: 
166: /* inventory */
167: .inv-grid{display:grid;grid-template-columns:repeat(auto-fill,72px);gap:8px;max-height:400px;overflow-y:auto;padding:4px}
168: .inv-cell{width:72px;height:72px;background:rgba(0,0,0,.4);border:1px solid rgba(216,180,90,.3);border-radius:5px;display:flex;flex-direction:column;align-items:center;justify-content:center;cursor:pointer;position:relative;font-size:24px}
169: .inv-cell:hover{border-color:var(--gold2)}
170: .inv-cell .q{position:absolute;bottom:2px;right:4px;font-size:10px;color:#fff}
171: .inv-cell.r-com{border-color:#9a9a90}.inv-cell.r-unc{border-color:#5aa04a}.inv-cell.r-rar{border-color:#4a7ad0}.inv-cell.r-epi{border-color:#a050d8}.inv-cell.r-len{border-color:#e0a030}.inv-cell.r-mit{border-color:#e05070}
172: .inv-tabs{display:flex;gap:6px;margin-bottom:12px;flex-wrap:wrap}
173: .inv-tab{padding:6px 14px;font-size:12px;letter-spacing:1px;background:rgba(0,0,0,.35);border:1px solid rgba(216,180,90,.3);border-radius:4px;color:var(--parch)}
174: .inv-tab.on{background:rgba(120,90,30,.6);color:#fff}
175: #inv-detail{margin-top:12px;padding:12px;background:rgba(0,0,0,.3);border:1px solid rgba(216,180,90,.25);border-radius:6px;min-height:80px;font-size:13px}
176: #inv-detail .id-name{color:var(--gold2);font-size:15px}
177: #inv-detail .id-desc{color:#b8a888;margin-top:4px;line-height:1.4}
178: #inv-detail .id-stat{color:#8fb07a;margin-top:4px}
179: .equip-row{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap}
180: .eq-slot{width:64px;height:64px;background:rgba(0,0,0,.4);border:1px dashed rgba(216,180,90,.35);border-radius:5px;display:flex;align-items:center;justify-content:center;font-size:22px;cursor:pointer;position:relative}
181: .eq-slot .eq-lbl{position:absolute;bottom:-14px;font-size:8px;color:#8a7850;width:100%;text-align:center;letter-spacing:.5px}
182: 
183: /* map */
184: #map-canvas{border:2px solid var(--border);border-radius:6px;background:#141008;display:block;max-width:82vw}
185: .map-side{margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
186: .travel-btn{padding:6px 12px;font-size:12px;background:rgba(60,46,20,.6);border:1px solid var(--border);border-radius:4px;color:var(--parch);letter-spacing:1px}
187: .travel-btn:hover{color:#fff}
188: 
189: /* quests panel */
190: .q-item{padding:10px;border-bottom:1px solid rgba(216,180,90,.2);cursor:pointer}
191: .q-item:hover{background:rgba(255,255,255,.04)}
192: .q-item .q-t{color:var(--gold2);font-size:15px;letter-spacing:1px}
193: .q-item .q-t.done{color:#7a9a68;text-decoration:line-through}
194: .q-item .q-d{font-size:12px;color:#b8a888;margin-top:3px;line-height:1.4}
195: .q-item .q-r{font-size:11px;color:#c9a227;margin-top:3px}
196: 
197: /* shop */
198: .shop-list{display:flex;flex-direction:column;gap:6px;min-width:420px}
199: .shop-item{display:flex;align-items:center;gap:12px;padding:9px 12px;background:rgba(0,0,0,.3);border:1px solid rgba(216,180,90,.25);border-radius:5px}
200: .shop-item .si-ico{font-size:24px;width:36px;text-align:center}
201: .shop-item .si-n{flex:1;font-size:14px}
202: .shop-item .si-p{color:var(--gold2);font-size:13px;margin-right:8px}
203: .buy-btn{padding:5px 16px;background:rgba(120,90,30,.5);border:1px solid var(--border);border-radius:4px;color:var(--parch);font-size:13px}
204: .buy-btn:hover{color:#fff}
205: 
206: /* controls / credits */
207: .ctl-table{width:100%;border-collapse:collapse;font-size:14px}
208: .ctl-table td{padding:7px 12px;border-bottom:1px solid rgba(216,180,90,.15)}
209: .ctl-table td:first-child{color:var(--gold2);letter-spacing:1px;width:180px}
210: .credits p{margin-bottom:8px;font-size:14px;color:#c8b890;text-align:center;line-height:1.6}
211: 
212: /* pause menu */
213: #pause-menu .pbox{text-align:center;min-width:340px}
214: #pause-menu button{display:block;width:100%;margin-bottom:10px;padding:12px;background:linear-gradient(180deg,rgba(58,44,20,.9),rgba(30,22,10,.9));border:1px solid var(--border);border-radius:6px;color:var(--parch);font-size:16px;letter-spacing:2px}
215: #pause-menu button:hover{color:#fff}
216: 
217: /* vignette / flash */
218: #vignette{position:absolute;inset:0;box-shadow:inset 0 0 180px rgba(0,0,0,.55);pointer-events:none}
219: #hurt-vignette{position:absolute;inset:0;box-shadow:inset 0 0 140px rgba(160,20,10,.0);pointer-events:none;transition:box-shadow .3s}
220: #night-tint{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 40%,rgba(5,8,20,.35))}
221: 
222: /* mobile */
223: #mobile-ui{position:absolute;inset:0;pointer-events:none;display:none}
224: #joystick{position:absolute;bottom:30px;left:30px;width:120px;height:120px;border-radius:50%;background:rgba(255,255,255,.06);border:2px solid rgba(216,180,90,.3);pointer-events:auto}
225: #joystick .stick{position:absolute;top:35px;left:35px;width:50px;height:50px;border-radius:50%;background:rgba(216,180,90,.35)}
226: #m-btns{position:absolute;bottom:24px;right:24px;display:grid;grid-template-columns:64px 64px;gap:10px;pointer-events:auto}
227: .m-btn{width:64px;height:64px;border-radius:50%;background:rgba(40,30,14,.7);border:2px solid rgba(216,180,90,.4);color:var(--gold2);font-size:11px;letter-spacing:1px;display:flex;align-items:center;justify-content:center;pointer-events:auto}
228: .m-btn:active{background:rgba(120,90,30,.8)}
229: #m-look{position:absolute;right:0;top:0;width:45%;height:70%;pointer-events:auto}
230: #fps-counter{position:absolute;bottom:6px;left:8px;font-size:10px;color:#6a5a38;letter-spacing:1px}
231: </style>
232: </head>
233: <body>
234: <div id="app"></div>
235: 
236: <!-- Loading -->
237: <div id="loading">
238:   <h1>CRÔNICAS DE AETHERIA</h1>
