350:       const label = typeof it.label === 'function' ? it.label() : it.label;
351:       if (label === 'Baú vazio') continue;
352:       const d = dist(pp.x, pp.z, it.pos.x, it.pos.z);
353:       if (d < (it.r || 2.5) && d < (best ? 3.4 : 99)) {
354:         if (it.cd && it._cdT > 0) continue;
355:         best = { type: 'world', it };
356:         bestLabel = label;
357:         bestAction = () => {
358:           if (it.cd) it._cdT = it.cd;
359:           it.action(this);
360:         };
361:         bestIcon = it.icon || '✋';
362:       }
363:     }
364:     // ervas tomadas
365:     if (best && best.type === 'world' && best.it.label === 'Coletar Erva Curativa') {
