import { chromium } from 'playwright-core';
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true,
  args: ['--no-sandbox','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader'] });
const page = await browser.newPage({ viewport: { width: 800, height: 500 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('404')) errors.push('CONSOLE: ' + m.text().slice(0, 200)); });
await page.goto('http://localhost:8099/', { waitUntil: 'load' });
await page.waitForSelector('#mainmenu:not(.hidden)', { timeout: 30000 });
await page.click('#mm-new');
await page.waitForTimeout(2000);

// desempenho leve para o teste headless
await page.evaluate(() => {
  const g = window.__game;
  g.settings.shadows = 0; g.daynight.setShadowQuality(0); g.renderer.shadowMap.enabled = false;
  g.fx.quality = 0;
});

const log = (...a) => console.log('[T]', ...a);
const waitFn = async (fn, timeoutMs = 30000, poll = 250) => {
  const t0 = Date.now();
  while (Date.now() - t0 < timeoutMs) {
    const v = await page.evaluate(fn).catch(() => null);
    if (v) return v;
    await page.waitForTimeout(poll);
  }
  return null;
};

// ---- 1. falar com o ancião ----
await page.evaluate(() => {
  const g = window.__game, e = g.npcs.get('elder');
  g.player.root.position.set(e.pos.x + 1.5, g.world.terrainHeight(e.pos.x + 1.5, e.pos.z + 1.5), e.pos.z + 1.5);
});
// aguarda o prompt de interação aparecer (prova que o scan por-frame funciona)
const prompt = await waitFn(() => {
  const el = document.getElementById('interact-prompt');
  return !el.classList.contains('hidden') ? el.textContent : null;
}, 15000);
log('PROMPT:', JSON.stringify(prompt));
await page.keyboard.press('KeyE');
const dlg = await waitFn(() => {
  const d = document.getElementById('dialog');
  if (d.classList.contains('hidden')) return null;
  return { name: document.getElementById('d-name').textContent, opts: [...document.querySelectorAll('.d-opt')].map(b => b.textContent) };
}, 15000);
log('DIALOG:', JSON.stringify(dlg));
await page.click('.d-opt'); // "Vou imediatamente!"
const q = await waitFn(() => window.__game.quests.active.map(a => a.id).join(',') || null, 10000);
log('QUESTS:', q);

// ---- 2. ir ao castelo e tocar o cristal ----
await page.evaluate(() => {
  const g = window.__game, c = g.world.crystalPos;
  g.player.root.position.set(c.x + 2.2, g.world.terrainHeight(c.x + 2.2, c.z + 1.5), c.z + 1.5);
  g.player.targetFacing = 0;
});
await page.keyboard.press('KeyE');
const cd = await waitFn(() => {
  const d = document.getElementById('dialog');
  if (d.classList.contains('hidden')) return null;
  return document.getElementById('d-name').textContent;
}, 15000);
log('CRYSTAL DIALOG:', JSON.stringify(cd));
await page.click('.d-opt'); // estender a mão
// cinemática 12s de tempo-de-jogo (dt limitado — pode demorar mais em headless)
const elem = await waitFn(() => {
  const g = window.__game;
  return g.story.testDone ? { element: g.player.element, chapter: g.story.chapter, grim: g.grimoire.visible } : null;
}, 90000);
log('ELEMENT:', JSON.stringify(elem));

// ---- 3. invasão ----
const inv = await waitFn(() => {
  const g = window.__game;
  return g.story.invasionActive ? { enemies: g.enemies.list.filter(e => !e.dead).length, quest: g.quests.active.map(a => a.id).join(',') } : null;
}, 60000);
log('INVASION:', JSON.stringify(inv));

await page.mouse.click(400, 250);
for (let w = 0; w < 3; w++) {
  await page.evaluate(() => { for (const e of window.__game.enemies.list) if (!e.dead) e.kill(); });
  await page.waitForTimeout(1500);
}
const after = await waitFn(() => {
  const g = window.__game;
  return g.story.invasionDone ? { chapter: g.story.chapter, quests: g.quests.active.map(a => a.id).join(','), level: g.player.level, gold: g.inventory.gold } : null;
}, 30000);
log('AFTER INVASION:', JSON.stringify(after));

// ---- 4. HUD panels ----
await page.keyboard.press('KeyG');
const grim = await waitFn(() => {
  const el = document.getElementById('panel-grimoire');
  return el.classList.contains('open') ? document.getElementById('grimoire-book').textContent.slice(0, 60) : null;
}, 8000);
log('GRIMOIRE:', JSON.stringify(grim));
await page.keyboard.press('KeyG');
await page.keyboard.press('KeyI');
const inv2 = await waitFn(() => document.getElementById('panel-inventory').classList.contains('open') || null, 8000);
log('INVENTORY:', JSON.stringify(inv2));
await page.keyboard.press('Escape');
await page.keyboard.press('KeyM');
const map = await waitFn(() => document.getElementById('panel-map').classList.contains('open') || null, 8000);
log('MAP:', JSON.stringify(map));
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

// ---- 5. magia ----
await page.evaluate(() => { const g = window.__game, c = g.world.crystalPos; g.player.root.position.set(c.x, g.world.terrainHeight(c.x, c.z), c.z + 8); });
await page.keyboard.press('Digit1');
const spell = await waitFn(() => {
  const g = window.__game;
  return (g.spellProjectiles.length > 0 || g.player.mana < g.player.maxMana) ? { projectiles: g.spellProjectiles.length, mana: Math.round(g.player.mana) } : null;
}, 10000);
log('SPELL:', JSON.stringify(spell));

// ---- 6. save + reload ----
await page.evaluate(() => window.__game.save.saveGame());
await page.reload({ waitUntil: 'load' });
await page.waitForSelector('#mainmenu:not(.hidden)', { timeout: 30000 });
const canContinue = await page.evaluate(() => !document.getElementById('mm-continue').disabled);
log('CONTINUE ENABLED:', canContinue);
await page.click('#mm-continue');
const loaded = await waitFn(() => {
  const g = window.__game;
  return (g.playing && !g.paused) ? { element: g.player.element, level: g.player.level, chapter: g.story.chapter, grim: g.grimoire.visible, pos: g.player.root.position.toArray().map(v => Math.round(v)) } : null;
}, 15000);
log('LOADED:', JSON.stringify(loaded));

await page.screenshot({ path: '/tmp/opencode/shot_final.jpg', quality: 72, type: 'jpeg' });
console.log('[T] ERRORS:', errors.length ? errors.slice(0, 10).join('\n') : 'nenhum');
await browser.close();

